import SwiftUI

/// Onboarding colour tokens (spec section 4.1). Every token is a Color Set in
/// `Assets.xcassets/Onboarding` with Any + Dark appearances, generated by
/// `Tools/make_onboarding_colors.py`. Do not lighten any token: contrast was measured.
///
/// These are separate from `SQColor` (the main app) on purpose: the values overlap in name
/// (`accent`, `ink`, `stone`) but differ in value.
enum OBColor {
    static let paper = Color("ob.paper")
    static let ink = Color("ob.ink")
    static let accent = Color("ob.accent")
    static let hole = Color("ob.hole")
    /// Passport page: stays cream in dark mode.
    static let page = Color("ob.page")

    /// Asset names of every token, for the resolution test.
    nonisolated static let assetNames = ["paper", "ink", "accent", "hole", "page"].map { "ob." + $0 }

    /// Stamp label ink and number ink. Fixed: stamps keep their physical identity in dark mode.
    nonisolated static let stampLabelInk: UInt32 = 0x2A2C29
    nonisolated static let stampNumberInk: UInt32 = 0x453F33
}
